      var horiz=key==="ArrowLeft"||key==="ArrowRight";
      var nv=Math.round(Math.min(1.2,Math.max(-.2,(horiz?eff.x:eff.y)+d))*1000)/1000;
      var patch=horiz?{x:nv}:{y:nv};
      if(svmMpOf(c))svmMpField(c,patch);
