  var s2=x.useState(!1),err=s2[0],setErr=s2[1];
  var s3=x.useState(!1),okd=s3[0],setOkd=s3[1];
  var s4=x.useState(props.url),url=s4[0],setUrl=s4[1];
  var s5=x.useState(!1),fbErr=s5[0],setFbErr=s5[1];
